532	  const maxPromptChars = opts.maxPromptChars ?? 4000;
533	  const notes: string[] = [];
534	
535	  const token = await getGitHubToken();
536	  const headers = getHeaders(token);
537	
538	  let tree: { ref: string; items: TreeItem[] } | null;
539	  try {
540	    tree = await fetchCheckpointTree(owner, repo, headers);
541	  } catch {
542	    return null;
543	  }
544	  if (!tree) return null;
545	
546	  const paths = tree.items.filter((t) => t.type === "blob").map((t) => t.path);
547	  const checkpointCount = Math.max(
548	    countCheckpointDirs(paths),
549	    tree.ref.startsWith(ENTIRE_REF_PREFIX) ? 1 : 0
550	  );
551	
552	  // Collect prompt samples.
553	  const promptSamples: string[] = [];
554	  let promptCount = 0;
555	  for (const p of paths.filter(isPromptFilePath)) {
556	    if (promptSamples.length >= maxPrompts) break;
557	    const content = await fetchBlobText(owner, repo, tree.ref, p, headers);
558	    if (content == null) continue;
559	    for (const prompt of content.split(PROMPT_SEPARATOR)) {
560	      const trimmed = prompt.trim();
561	      if (!trimmed) continue;
562	      promptCount++;
563	      if (promptSamples.length < maxPrompts) {
564	        promptSamples.push(trimmed.slice(0, maxPromptChars));
565	      }
566	    }
567	  }
568	
569	  // Collect agents + files-touched from metadata.json blobs (bounded).
570	  const agents = new Set<string>();
571	  const files = new Set<string>();
572	  for (const p of paths.filter((x) => /(^|\/)metadata\.json$/.test(x)).slice(0, maxPrompts)) {
573	    const content = await fetchBlobText(owner, repo, tree.ref, p, headers);
574	    if (content == null) continue;
575	    try {
576	      const meta = JSON.parse(content) as Record<string, unknown>;
577	      for (const key of ["agent", "Agent", "agent_type"]) {
578	        const v = meta[key];
579	        if (typeof v === "string" && v.trim()) agents.add(v.trim());
580	      }
581	      for (const key of ["files_touched", "filesTouched", "files"]) {
582	        const v = meta[key];
583	        if (Array.isArray(v)) v.forEach((f) => typeof f === "string" && files.add(f));
584	      }
585	      if (promptCount === 0) promptCount += promptCountFromMetadata(meta);
586	    } catch {
587	      // ignore malformed metadata
588	    }
589	  }
590	
591	  // Signing status: check the latest commit on the checkpoint branch for a
592	  // verified signature. Best-effort; absence is not penalized here.
593	  let signed = false;
594	  try {
595	    const refForCommit = tree.ref.startsWith("refs/")
596	      ? tree.ref
597	      : `heads/${tree.ref}`;
598	    const commitsRes = await fetch(
599	      `https://api.github.com/repos/${owner}/${repo}/commits?sha=${encodeURIComponent(
600	        refForCommit.replace(/^heads\//, "")
601	      )}&per_page=1`,
602	      { headers }
603	    );
604	    if (commitsRes.ok) {
605	      const arr = (await commitsRes.json()) as Array<{
606	        commit?: { verification?: { verified?: boolean } };
607	      }>;
608	      signed = !!arr?.[0]?.commit?.verification?.verified;
609	    }
610	  } catch {
611	    // ignore
612	  }
613	
614	  if (promptSamples.length === 0 && checkpointCount === 0) {
615	    notes.push("Checkpoint branch present but no readable prompts or checkpoints.");
616	  }
617	
618	  return {
619	    resolvedRef: tree.ref,
620	    checkpointCount,
621	    promptCount,
622	    promptSamples,
623	    agentsDetected: [...agents],
624	    filesTouched: [...files].slice(0, 200),
625	    signed,
626	    notes,
627	  };
628	}
