83	function detectFrameworks(files: RepoFile[]): string[] {
84	  const frameworks: string[] = [];
85	
86	  const packageJson = files.find((f) => f.path === "package.json");
87	  if (packageJson) {
88	    try {
89	      const pkg = JSON.parse(packageJson.content);
90	      const allDeps = {
91	        ...(pkg.dependencies ?? {}),
92	        ...(pkg.devDependencies ?? {}),
93	      };
94	      for (const [framework, packages] of Object.entries(FRAMEWORK_PATTERNS)) {
95	        if (packages.some((p) => p in allDeps)) {
96	          frameworks.push(framework);
97	        }
98	      }
99	    } catch { /* skip */ }
100	  }
101	
102	  // Python frameworks from requirements.txt
103	  const reqTxt = files.find((f) =>
104	    f.path === "requirements.txt" || f.path === "requirements/base.txt"
105	  );
106	  if (reqTxt) {
107	    const content = reqTxt.content.toLowerCase();
108	    if (content.includes("django")) frameworks.push("Django");
109	    if (content.includes("flask")) frameworks.push("Flask");
110	    if (content.includes("fastapi")) frameworks.push("FastAPI");
111	  }
112	
113	  return [...new Set(frameworks)];
114	}
