162	  // Get tree recursively
163	  const treeRes = await fetch(
164	    `https://api.github.com/repos/${owner}/${cleanRepo}/git/trees/${defaultBranch}?recursive=1`,
165	    { headers }
166	  );
167	  if (!treeRes.ok) throw new Error(`GitHub tree API error: ${treeRes.status}`);
168	  const treeData = await treeRes.json();
169	  const treeItems = (treeData.tree ?? []) as Array<{
170	    path: string; type: string; size?: number; sha: string; mode?: string;
171	  }>;
172	
173	  // Get commit count (from first page with per_page=1, read total from Link header)
174	  let commitCount = 0;
175	  try {
176	    const commitsRes = await fetch(
177	      `https://api.github.com/repos/${owner}/${cleanRepo}/commits?per_page=1`,
178	      { headers }
179	    );
