189	  const languages: Record<string, number> = {};
190	  let hasReadme = false;
191	  let hasDockerfile = false;
192	  let hasTests = false;
193	  let hasCi = false;
194	
195	  for (const item of allBlobs) {
196	    if (isIgnoredPath(item.path)) continue;
197	
198	    const filename = item.path.split("/").pop() ?? "";
199	    const ext = getExtension(item.path);
200	    const size = item.size ?? 0;
201	
202	    // Language counting
203	    const lang = EXT_LANGUAGE[ext];
204	    if (lang) {
