211	    if (filename === "Dockerfile" || filename === "docker-compose.yml") hasDockerfile = true;
212	    if (item.path.includes(".github/workflows/")) hasCi = true;
213	    if (item.path.split("/").some((s) => TEST_DIRS.has(s))) hasTests = true;
214	  }
215	
216	  // Filter and download relevant files
217	  const relevantItems = allBlobs.filter((item) => {
218	    if (isIgnoredPath(item.path)) return false;
219	    if (!isRelevantFile(item.path)) return false;
220	    if (item.size && item.size > 50000) return false; // Skip files > 50KB
221	    return true;
222	  });
223	
